targets.rawSql:
SELECT 'Thu phí sàn' AS "Khoản",take AS "VND" FROM mart.platform_pnl WHERE refresh_id = ${refresh_id:raw}
UNION ALL SELECT 'Ưu đãi sàn',platform_promo_cost FROM mart.platform_pnl WHERE refresh_id = ${refresh_id:raw}
UNION ALL SELECT 'Ưu đãi shop',seller_promo_cost FROM mart.platform_pnl WHERE refresh_id = ${refresh_id:raw}
UNION ALL SELECT 'Hoàn do trả hàng',return_refunds FROM mart.platform_pnl WHERE refresh_id = ${refresh_id:raw}

SELECT 'Trả hàng' AS "Nguyên nhân",return_refunds AS "VND" FROM mart.platform_pnl WHERE refresh_id = ${refresh_id:raw}
UNION ALL SELECT 'Hủy / giao thất bại',cancellation_refunds FROM mart.platform_pnl WHERE refresh_id = ${refresh_id:raw}
UNION ALL SELECT 'Thanh toán trễ',late_payment_refunds FROM mart.platform_pnl WHERE refresh_id = ${refresh_id:raw}
